const fs = await import('node:fs');
const path = await import('node:path');
const inputPath = process.env.INPUT_PATH;
if (!inputPath) throw new Error('INPUT_PATH is required');
if (!fs.existsSync(inputPath)) throw new Error(`Input file not found: ${inputPath}`);
const stat = fs.statSync(inputPath);
if (!stat.isFile()) throw new Error(`Input path is not a file: ${inputPath}`);
globalThis.inputPath = inputPath;
globalThis.outputPath = process.env.OUTPUT_PATH || path.join(path.dirname(inputPath), 'output.md');

const csv = (await import('csv-parser')).default;
const fs = await import('node:fs');
const results = [];
let headers = [];

await new Promise((resolve, reject) => {
  fs.createReadStream(globalThis.inputPath)
    .pipe(csv())
    .on('headers', (h) => { headers = h; })
    .on('data', (data) => results.push(data))
    .on('end', () => resolve())
    .on('error', (err) => reject(err));
});

if (results.length === 0) throw new Error('No data rows found in CSV');

const escapeCell = (val) => {
  if (val === null || val === undefined) return '';
  return String(val).replace(/\|/g, '\\|').replace(/\n/g, '<br>');
};

let md = '| ' + headers.map(h => escapeCell(h)).join(' | ') + ' |\n';
md += '|' + headers.map(() => ' --- ').join('|') + '|\n';
for (const row of results) {
  const cells = headers.map(h => escapeCell(row[h]));
  md += '| ' + cells.join(' | ') + ' |\n';
}

globalThis.markdownContent = md;
globalThis.rowCount = results.length;

const fs = await import('node:fs');
fs.writeFileSync(globalThis.outputPath, globalThis.markdownContent, 'utf8');
console.log(JSON.stringify({
  output_path: globalThis.outputPath,
  row_count: globalThis.rowCount
}));
